mini-api/docs/flex-inference\\n- https://ai.google.dev/gemini-api/docs/priority-inference\\n"},"required":true,"default":"standard","min":null,"max":null,"precision":null,"options":["flex","standard","priority"]},{"name":"json_schema","use_template":"json_schema","label":{"en_US":"json_schema"},"type":"string","help":{"en_US":"Set a response json schema will ensure LLM to adhere it.","zh_Hans":"设置返回的json schema，llm将按照它返回"},"required":false,"default":null,"min":null,"max":null,"precision":null,"options":[]}],"pricing":{"input":"0.25","output":"1.5","unit":"0.000001","currency":"USD"}},{"model":"gemini-3.1-pro-preview-customtools","label":{"en_US":"Gemini 3.1 Pro Preview (Custom Tools)"},"model_type":"llm","features":["tool-call","multi-tool-call","agent-thought","vision","stream-tool-call","document","video","audio","structured-output"],"fetch_from":"predefined-model","model_properties":{"context_size":1048576,"mode":"chat"},"deprecated":false,"parameter_rules":[{"name":"temperature","use_template":"temperature","label":{"en_US":"Temperature","zh_Hans":"温度"},"type":"float","help":{"en_US":"For Gemini 3, best results at default 1.0. Lower values may impact reasoning.","zh_Hans":"对于 Gemini 3，使用默认值 1.0 可获得最佳效果。数值过低可能会影响推理能力。"},"required":true,"default":1,"min":0,"max":2,"precision":2,"options":[]},{"name":"top_p","use_template":"top_p","label":{"en_US":"top_p"},"type":"float","help":{"en_US":"Controls diversity via nucleus sampling: 0.5 means half of all likelihood-weighted options are considered.","ja_JP":"核サンプリングを通じて多様性を制御します：0.5は、すべての可能性加权オプションの半分を考慮します。","zh_Hans":"通过核心采样控制多样性：0.5表示考虑了一半的所有可能性加权选项。","pt_BR":"Controla a diversidade via amostragem de núcleo: 0.5 significa que metade das opções com maior probabilidade são consideradas."},"required":false,"default":0.95,"min":0,"max":1,"precision":2,"options":[]},{"name":"include_thoughts","use_template":null,"label":{"en_US":"Include thoughts","zh_Hans":"返回思考过程"},"type":"boolean","help":{"en_US":"Indicates whether to include thoughts in the response. If true, thoughts are returned only if the model supports thought and thoughts are available. Default is false.","zh_Hans":"是否返回思考过程。若为 true 则只有模型支持思考且启动思考模式时才返回思考过程。默认为 false。"},"required":true,"default":false,"min":null,"max":null,"precision":null,"options":[]},{"name":"media_resolution","use_template":null,"label":{"en_US":"Media resolution","zh_Hans":"媒体分辨率"},"type":"string","help":{"en_US":"Gemini 3 introduces fine-grained control over multimodal visual processing via the `media_resolution` parameter. Higher resolution improves the model's ability to read small text or recognize fine details, but increases token usage and latency.\\n\\nRecommended Settings:\\n- Images: `media_resolution_high` (1120 tokens) - Recommended for most image analysis tasks to ensure best quality.\\n- PDF: `media_resolution_medium` (560 tokens) - Great for document understanding; quality usually saturates at medium.\\n- Video (Regular): `media_resolution_low` or `medium` (70 tokens/frame) - Sufficient for most action recognition and description tasks.\\n- Video (Text-heavy): `media_resolution_high` (280 tokens/frame) - Needed only when use cases involve reading dense text (OCR) or tiny details in video frames.\\n\\nNote: If not specified, the model uses the best default value based on the media type.\\n","zh_Hans":"Gemini 3 通过 `media_resolution` 参数引入了对多模态视觉处理的精细控制。分辨率越高，模型读取细小文本或识别细微细节的能力就越强，但会增加令牌用量和延迟时间。\\n\\n推荐设置：\\n- 图片：`media_resolution_high` (1120 tokens) - 建议用于大多数图片分析任务，以确保获得最佳质量。\\n- PDF：`media_resolution_medium` (560 tokens) - 非常适合文档理解；质量通常在 medium 时达到饱和。\\n- 视频（常规）：`media_resolution_low` 或 `medium` (70 tokens/帧) - 对于大多数动作识别和描述任务来说已经足够。\\n- 视频（文字较多）：`media_resolution_high` (280 tokens/帧) - 仅当用例涉及读取密集文本 (OCR) 或视频帧中的微小细节时才需要。\\n\\n注意：如果不指定，模型会根据媒体类型使用最佳默认值。\\n"},"required":true,"default":"Default","min":null,"max":null,"precision":null,"options":["Default","Low","Medium","High"]},{"name":"thinking_level","use_template":null,"label":{"en_US":"Thinking level","zh_Hans":"思考层级"},"type":"string","help":{"en_US":"Indicates the thinking level. Default is High.","zh_Hans":"思考层级。默认为 High。"},"required":true,"default":"High","min":null,"max":null,"precision":null,"options":["Low","High"]},{"name":"grounding","use_template":null,"label":{"en_US":"Grounding","ja_JP":"事実チェック","zh_Hans":"事实核查"},"type":"boolean","help":{"en_US":"Grounding with Google Search","ja_JP":"Google 検索に基づいた応答をします。","zh_Hans":"Google 事实核查"},"required":true,"default":false,"min":null,"max":null,"precision":null,"options":[]},{"name":"url_context","use_template":null,"label":{"en_US":"URL context","ja_JP":"網羅閲覧","zh_Hans":"链接详情"},"type":"boolean","help":{"en_US":"Browse the url context","ja_JP":"リンク先の詳細情報を取得し、文脈を理解します。","zh_Hans":"获取并分析该链接的详细信息，为回答提供参考依据。"},"required":true,"default":false,"min":null,"max":null,"precision":null,"options":[]},{"name":"code_execution","use_template":null,"label":{"en_US":"Code execution","ja_JP":"コード実行","zh_Hans":"代码执行"},"type":"boolean","help":{"en_US":"Lets Gemini use code to solve complex tasks","ja_JP":"Gemini にコードを使って複雑なタスクを解決させましょう。","zh_Hans":"让 Gemini 使用代码来解决复杂任务。"},"required":true,"default":false,"min":null,"max":null,"precision":null,"options":[]},{"name":"max_output_tokens","use_template":"max_tokens","label":{"en_US":"Output length","zh_Hans":"输出长度"},"type":"int","help":{"en_US":"The maximum number of tokens to generate in the response.","zh_Hans":"模型单次输出的最大 tokens 数。"},"required":true,"default":65536,"min":1,"max":65536,"precision":0,"options":[]},{"name":"flex_inference","use_template":null,"label":{"en_US":"Flex inference","zh_Hans":"Flex 推理"},"type":"boolean","help":{"en_US":"Use the Gemini Flex service tier (lower cost, best-effort latency). See https://ai.google.dev/gemini-api/docs/flex-inference","zh_Hans":"使用 Gemini Flex 服务层级（约半价、尽力而为型延迟）。详见 https://ai.google.dev/gemini-api/docs/flex-inference?hl=zh-cn"},"required":true,"default":false,"min":null,"max":null,"precision":null,"options":[]},{"name":"json